export default JSON.parse("{\"workId\":\"han-fei-zi\",\"chapter\":{\"id\":\"han-fei-zi_ch-23\",\"workId\":\"han-fei-zi\",\"order\":23,\"title\":\"喻老\",\"difficulty\":4,\"estimatedMinutes\":11,\"passageIds\":[\"han-fei-zi_ch-23_p-1\",\"han-fei-zi_ch-23_p-2\",\"han-fei-zi_ch-23_p-3\",\"han-fei-zi_ch-23_p-4\",\"han-fei-zi_ch-23_p-5\",\"han-fei-zi_ch-23_p-6\",\"han-fei-zi_ch-23_p-7\",\"han-fei-zi_ch-23_p-8\",\"han-fei-zi_ch-23_p-9\",\"han-fei-zi_ch-23_p-10\",\"han-fei-zi_ch-23_p-11\",\"han-fei-zi_ch-23_p-12\",\"han-fei-zi_ch-23_p-13\",\"han-fei-zi_ch-23_p-14\",\"han-fei-zi_ch-23_p-15\",\"han-fei-zi_ch-23_p-16\",\"han-fei-zi_ch-23_p-17\",\"han-fei-zi_ch-23_p-18\",\"han-fei-zi_ch-23_p-19\",\"han-fei-zi_ch-23_p-20\",\"han-fei-zi_ch-23_p-21\",\"han-fei-zi_ch-23_p-22\"],\"tags\":[\"法家\",\"帝王術\",\"法術勢\"]},\"passages\":[{\"id\":\"han-fei-zi_ch-23_p-1\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":1,\"canonicalText\":\"天下有道無急患則曰靜，遽傳不用，故曰：「卻走馬以糞。」天下無道，攻擊不休，相守數年不已，甲冑生蟣蝨，鷰雀處帷幄，而兵不歸，故曰：「戎馬生於郊。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-1_s-1\",\"han-fei-zi_ch-23_p-1_s-2\",\"han-fei-zi_ch-23_p-1_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"天下有道無急患則說道：靜，遽傳不用，因此韓絕不是子評論說道：卻走馬以糞。天下無道，攻擊不休，相守數年不已，甲冑生蟣蝨，鷰雀處帷幄，而且兵不歸，因此韓絕不是子評論說道：戎馬生於郊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「天下有道無急患則曰靜，遽傳不用，故曰：「卻走馬以糞」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「天下有道無急患則曰靜，遽傳不用，故曰：「卻走馬以糞。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-2\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":2,\"canonicalText\":\"翟人有獻豐狐、玄豹之皮於晉文公，文公受客皮而歎曰：「此以皮之美自為罪。」夫治國者以名號為罪，徐偃王是也。以城與地為罪，虞、虢是也。故曰：「罪莫大於可欲。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-2_s-1\",\"han-fei-zi_ch-23_p-2_s-2\",\"han-fei-zi_ch-23_p-2_s-3\",\"han-fei-zi_ch-23_p-2_s-4\",\"han-fei-zi_ch-23_p-2_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"翟人有獻豐狐、玄豹的皮於晉文公，文公受客皮而且歎說道：此以皮的美自為罪。夫治國的人或事物以名號為罪，徐偃王是啊。以城與地為罪，虞、虢是啊。因此韓絕不是子評論說道：罪莫大於可欲。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「翟人有獻豐狐、玄豹之皮於晉文公，文公受客皮而歎曰：「此以皮之美自為罪」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「翟人有獻豐狐、玄豹之皮於晉文公，文公受客皮而歎曰：「……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-3\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":3,\"canonicalText\":\"智伯兼範、中行而攻趙不已，韓、魏反之，軍敗晉陽，身死高梁之東，遂卒被分，漆其首以為溲器，故曰：「禍莫大於不知足。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-3_s-1\",\"han-fei-zi_ch-23_p-3_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"智伯兼範、中行而且攻趙不已，韓、魏反的，軍敗晉陽，身死高梁的東，遂卒被分，漆他的首以為溲器，因此韓絕不是子評論說道：禍莫大於不知足。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「智伯兼範、中行而攻趙不已，韓、魏反之，軍敗晉陽，身死高梁之東，遂卒被分，漆其首以為溲器，故曰：「禍莫大於不知足」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「智伯兼範、中行而攻趙不已，韓、魏反之，軍敗晉陽，身死……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-4\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":4,\"canonicalText\":\"虞君欲屈產之乘，與垂棘之璧，不聽宮之奇，故邦亡身死，故曰：「咎莫憯於欲得。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-4_s-1\",\"han-fei-zi_ch-23_p-4_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"虞君主統治者欲屈產的乘，與垂棘的璧，不聽宮的奇，所以邦亡身死，因此韓絕不是子評論說道：咎莫憯於欲得。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「虞君欲屈產之乘，與垂棘之璧，不聽宮之奇，故邦亡身死，故曰：「咎莫憯於欲得」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「虞君欲屈產之乘，與垂棘之璧，不聽宮之奇，故邦亡身死，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-5\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":5,\"canonicalText\":\"邦以存為常，霸王其可也。身以生為常，富貴其可也。不欲自害則邦不亡身不死，故曰：「知足之為足矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-5_s-1\",\"han-fei-zi_ch-23_p-5_s-2\",\"han-fei-zi_ch-23_p-5_s-3\",\"han-fei-zi_ch-23_p-5_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"邦以存為常，霸王他的可啊。身以生為常，富貴他的可啊。不欲自害則邦不亡身不死，因此韓絕不是子評論說道：知足的為足矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「邦以存為常，霸王其可也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「邦以存為常，霸王其可也。身以生為常，富貴其可也。不欲……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-6\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":6,\"canonicalText\":\"楚莊王既勝狩於河雍，歸而賞孫叔敖，孫叔敖請漢間之地，沙石之處。楚邦之法，祿臣再世而收地，唯孫叔敖獨在。此不以其邦為收者，瘠也，故九世而祀不絕。故曰：「善建不拔，善抱不脫，子孫以其祭祀世世不輟」，孫叔敖之謂也。\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-6_s-1\",\"han-fei-zi_ch-23_p-6_s-2\",\"han-fei-zi_ch-23_p-6_s-3\",\"han-fei-zi_ch-23_p-6_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楚莊王既勝狩於河雍，歸而且賞賜恩惠孫叔敖，孫叔敖請漢間的地，沙石的處。楚邦的國家法度法規，祿臣下僚屬再世而且收地，唯孫叔敖獨在。此不以他的邦為收的人或事物，瘠啊，所以九世而且祀不絕。因此韓絕不是子評論說道：善建不拔，善抱不脫，子孫以他的祭祀世世不輟，孫叔敖的謂啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「楚莊王既勝狩於河雍，歸而賞孫叔敖，孫叔敖請漢間之地，沙石之處」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「楚莊王既勝狩於河雍，歸而賞孫叔敖，孫叔敖請漢間之地，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-7\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":7,\"canonicalText\":\"制在己曰重，不離位曰靜。重則能使輕，靜則能使躁。故曰：「重為輕根，靜為躁君。故曰君子終日行不離輜重也。」邦者，人君之輜重也。主父生傳其邦，此離其輜重者也。故雖有代、雲中之樂，超然已無趙矣。主父，萬乘之主，而以身輕於天下，無勢之謂輕，離位之謂躁，是以生幽而死。故曰：「輕則失臣，躁則失君」，主父之謂也。\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-7_s-1\",\"han-fei-zi_ch-23_p-7_s-2\",\"han-fei-zi_ch-23_p-7_s-3\",\"han-fei-zi_ch-23_p-7_s-4\",\"han-fei-zi_ch-23_p-7_s-5\",\"han-fei-zi_ch-23_p-7_s-6\",\"han-fei-zi_ch-23_p-7_s-7\",\"han-fei-zi_ch-23_p-7_s-8\",\"han-fei-zi_ch-23_p-7_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"制在己說道：重，不離位說道：靜。重則能使輕，靜則能使躁。因此韓絕不是子評論說道：重為輕根，靜為躁君主統治者。因此韓絕不是子評論說道：君主統治者子終日行不離輜重啊。邦的人或事物，人君主統治者的輜重啊。主父生傳他的邦，此離他的輜重的人或事物啊。所以雖有代、雲中的樂，超然已無趙矣。主父，萬乘的主，而且以身輕於天下，無至高權力威勢的謂輕，離位的謂躁，是以生幽而且死。因此韓絕不是子評論說道：輕則失臣下僚屬，躁則失君主統治者，主父的謂啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 7 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「制在己曰重，不離位曰靜」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「制在己曰重，不離位曰靜。重則能使輕，靜則能使躁。故曰……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-8\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":8,\"canonicalText\":\"勢重者，人君之淵也。君人者勢重於人臣之閒，失則不可復得也。簡公失之於田成，晉公失之於六卿，而邦亡身死。故曰：「魚不可脫於深淵。」賞罰者，邦之利器也，在君則制臣，在臣則勝君。君見賞，臣則損之以為德；君見罰，臣則益之以為威。人君見賞而人臣用其勢，人君見罰而人臣乘其威。故曰：「邦之利器不可以示人。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-8_s-1\",\"han-fei-zi_ch-23_p-8_s-2\",\"han-fei-zi_ch-23_p-8_s-3\",\"han-fei-zi_ch-23_p-8_s-4\",\"han-fei-zi_ch-23_p-8_s-5\",\"han-fei-zi_ch-23_p-8_s-6\",\"han-fei-zi_ch-23_p-8_s-7\",\"han-fei-zi_ch-23_p-8_s-8\",\"han-fei-zi_ch-23_p-8_s-9\",\"han-fei-zi_ch-23_p-8_s-10\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"至高權力威勢重的人或事物，人君主統治者的淵啊。君主統治者人的人或事物至高權力威勢重於人臣下僚屬的閒，失則不可復得啊。簡公失的於田成，晉公失的於六卿，而且邦亡身死。因此韓絕不是子評論說道：魚不可脫於深淵。賞賜恩惠刑罰制裁的人或事物，邦的利器啊，在君主統治者則制臣下僚屬，在臣下僚屬則勝君主統治者。君主統治者見賞賜恩惠，臣下僚屬則損的以為德；君主統治者見刑罰制裁，臣下僚屬則益的以為威。人君主統治者見賞賜恩惠而且人臣下僚屬用他的至高權力威勢，人君主統治者見刑罰制裁而且人臣下僚屬乘他的威。因此韓絕不是子評論說道：邦的利器不可以示人。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 8 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「勢重者，人君之淵也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「勢重者，人君之淵也。君人者勢重於人臣之閒，失則不可復……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-9\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":9,\"canonicalText\":\"越王入宦於吳，而觀之伐齊以弊吳。吳兵既勝齊人於艾陵，張之於江、濟，強之於黃池，故可制於五湖。故曰：「將欲翕之，必固張之；將欲弱之，必固強之。」晉獻公將欲襲虞，遺之以璧馬；知伯將襲仇由，遺之以廣車。故曰：「將欲取之，必固與之。」起事於無形，而要大功於天下，是謂微明。處小弱而重自卑謂損弱勝強也。\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-9_s-1\",\"han-fei-zi_ch-23_p-9_s-2\",\"han-fei-zi_ch-23_p-9_s-3\",\"han-fei-zi_ch-23_p-9_s-4\",\"han-fei-zi_ch-23_p-9_s-5\",\"han-fei-zi_ch-23_p-9_s-6\",\"han-fei-zi_ch-23_p-9_s-7\",\"han-fei-zi_ch-23_p-9_s-8\",\"han-fei-zi_ch-23_p-9_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"越王入宦於吳，而且觀的伐齊以弊吳。吳兵既勝齊人於艾陵，張的於江、濟，強的於黃池，所以可制於五湖。因此韓絕不是子評論說道：將欲翕的，必固張的；將欲弱的，必固強的。晉獻公將欲襲虞，遺的以璧馬；知伯將襲仇由，遺的以廣車。因此韓絕不是子評論說道：將欲取的，必固與的。起事於無形，而且要大功於天下，是謂微明。處小弱而且重自卑謂損弱勝強啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 9 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「越王入宦於吳，而觀之伐齊以弊吳」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「越王入宦於吳，而觀之伐齊以弊吳。吳兵既勝齊人於艾陵，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-10\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":10,\"canonicalText\":\"有形之類，大必起於小；行久之物，族必起於少。故曰：「天下之難事必作於易，天下之大事必作於細。」是以欲制物者於其細也，故曰：「圖難於其易也，為大於其細也。」千丈之隄以螻蟻之穴潰，百尺之室以突隙之煙焚。故曰：白圭之行隄也塞其穴，丈人之慎火也塗其隙。是以白圭無水難，丈人無火患。此皆慎易以避難，敬細以遠大者也。扁鵲見蔡桓公，立有間，扁鵲曰：「君有疾在腠理，不治將恐深。」桓侯曰：「寡人無。」扁鵲出，桓侯曰：「醫之好治不病以為功。」居十日，扁鵲復見曰：「君之病在肌膚，不治將益深。」桓侯不應。扁鵲出，桓侯又不悅。居十日，扁鵲復見曰：「君之病在腸胃，不治將益深。」桓侯又不應。扁鵲出，桓侯又不悅。居十日，扁鵲望桓侯而還走。桓侯故使人問之，扁鵲曰：「疾在腠理，湯熨之所及也；在肌膚，鍼石之所及也；在腸胃，火齊之所及也；在骨髓，司命之所屬，無奈何也。今在骨髓，臣是以無請也。」居五日，桓公體痛，使人索扁鵲，已逃秦矣，桓侯遂死。故良醫之治病也，攻之於腠理，此皆爭之於小者也。夫事之禍福亦有腠理之地，故曰：聖人蚤從事焉。\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-10_s-1\",\"han-fei-zi_ch-23_p-10_s-2\",\"han-fei-zi_ch-23_p-10_s-3\",\"han-fei-zi_ch-23_p-10_s-4\",\"han-fei-zi_ch-23_p-10_s-5\",\"han-fei-zi_ch-23_p-10_s-6\",\"han-fei-zi_ch-23_p-10_s-7\",\"han-fei-zi_ch-23_p-10_s-8\",\"han-fei-zi_ch-23_p-10_s-9\",\"han-fei-zi_ch-23_p-10_s-10\",\"han-fei-zi_ch-23_p-10_s-11\",\"han-fei-zi_ch-23_p-10_s-12\",\"han-fei-zi_ch-23_p-10_s-13\",\"han-fei-zi_ch-23_p-10_s-14\",\"han-fei-zi_ch-23_p-10_s-15\",\"han-fei-zi_ch-23_p-10_s-16\",\"han-fei-zi_ch-23_p-10_s-17\",\"han-fei-zi_ch-23_p-10_s-18\",\"han-fei-zi_ch-23_p-10_s-19\",\"han-fei-zi_ch-23_p-10_s-20\",\"han-fei-zi_ch-23_p-10_s-21\",\"han-fei-zi_ch-23_p-10_s-22\",\"han-fei-zi_ch-23_p-10_s-23\",\"han-fei-zi_ch-23_p-10_s-24\",\"han-fei-zi_ch-23_p-10_s-25\",\"han-fei-zi_ch-23_p-10_s-26\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"有形的類，大必起於小；行久的物，族必起於少。因此韓絕不是子評論說道：天下的難事必作於易，天下的大事必作於細。是以欲制物的人或事物於他的細啊，因此韓絕不是子評論說道：圖難於他的易啊，為大於他的細啊。千丈的隄以螻蟻的穴潰，百尺的室以突隙的煙焚。因此韓絕不是子評論說道：白圭的行隄啊塞他的穴，丈人的慎火啊塗他的隙。是以白圭無水難，丈人無火患。此皆慎易以避難，敬細以遠大的人或事物啊。扁鵲見蔡桓公，立有間，扁鵲說道：君主統治者有疾在腠理，不治將恐深。桓侯說道：寡人無。扁鵲出，桓侯說道：醫的好治不病以為功。居十日，扁鵲復見說道：君主統治者的病在肌膚，不治將益深。桓侯不應。扁鵲出，桓侯又不悅。居十日，扁鵲復見說道：君主統治者的病在腸胃，不治將益深。桓侯又不應。居十日，扁鵲望桓侯而且還走。桓侯所以使人問的，扁鵲說道：疾在腠理，湯熨的所及啊；在肌膚，鍼石的所及啊；在腸胃，火齊的所及啊；在骨髓，司命的所屬，無奈何啊。今在骨髓，臣下僚屬是以無請啊。居五日，桓公體痛，使人索扁鵲，已逃秦矣，桓侯遂死。所以良醫的治病啊，攻的於腠理，此皆爭的於小的人或事物啊。夫事的禍福亦有腠理的地，因此韓絕不是子評論說道：聖人蚤從事焉。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 10 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「有形之類，大必起於小」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「有形之類，大必起於小；行久之物，族必起於少。故曰：「……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-11\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":11,\"canonicalText\":\"昔晉公子重耳出亡過鄭，鄭君不禮，叔瞻諫曰：「此賢公子也，君厚待之，可以積德。」鄭君不聽。叔瞻又諫曰：「不厚待之，不若殺之，無令有後患。」鄭君又不聽。及公子返晉邦，舉兵伐鄭，大破之，取八城焉。晉獻公以垂棘之璧假道於虞而伐虢，大夫宮之奇諫曰：「不可。脣亡而齒寒，虞、虢相救，非相德也。今日晉滅虢，明日虞必隨之亡。」虞君不聽，受其璧而假之道。晉已取虢，還，反滅虞。此二臣者皆爭於腠理者也，而二君不用也。然則叔瞻、宮之奇亦虞、鄭之扁鵲也，而二君不聽，故鄭以破，虞以亡。故曰：「其安易持也，其未兆易謀也。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-11_s-1\",\"han-fei-zi_ch-23_p-11_s-2\",\"han-fei-zi_ch-23_p-11_s-3\",\"han-fei-zi_ch-23_p-11_s-4\",\"han-fei-zi_ch-23_p-11_s-5\",\"han-fei-zi_ch-23_p-11_s-6\",\"han-fei-zi_ch-23_p-11_s-7\",\"han-fei-zi_ch-23_p-11_s-8\",\"han-fei-zi_ch-23_p-11_s-9\",\"han-fei-zi_ch-23_p-11_s-10\",\"han-fei-zi_ch-23_p-11_s-11\",\"han-fei-zi_ch-23_p-11_s-12\",\"han-fei-zi_ch-23_p-11_s-13\",\"han-fei-zi_ch-23_p-11_s-14\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"昔晉公子重耳出亡過鄭，鄭君主統治者不禮，叔瞻諫說道：此賢公子啊，君主統治者厚待的，可以積德。鄭君主統治者不聽。叔瞻又諫說道：不厚待的，不若殺的，無令有後患。鄭君主統治者又不聽。及公子返晉邦，舉兵伐鄭，大破的，取八城焉。晉獻公以垂棘的璧假道於虞而且伐虢，大夫宮的奇諫說道：不可。脣亡而且齒寒，虞、虢相救，絕不是相德啊。今日晉滅虢，明日虞必隨的亡。虞君主統治者不聽，受他的璧而且假的道。晉已取虢，還，反滅虞。此二臣下僚屬的人或事物皆爭於腠理的人或事物啊，而且二君主統治者不用啊。然則叔瞻、宮的奇亦虞、鄭的扁鵲啊，而且二君主統治者不聽，所以鄭以破，虞以亡。因此韓絕不是子評論說道：他的安易持啊，他的未兆易謀啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 11 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「昔晉公子重耳出亡過鄭，鄭君不禮，叔瞻諫曰：「此賢公子也，君厚待之，可以積德」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「昔晉公子重耳出亡過鄭，鄭君不禮，叔瞻諫曰：「此賢公子……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-12\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":12,\"canonicalText\":\"昔者紂為象箸而箕子怖。以為象箸必不加於土鉶，必將犀玉之杯。象箸玉杯必不羹菽藿，則必旄象豹胎。旄象豹胎必不衣短褐而食於茅屋之下，則錦衣九重，廣室高臺。吾畏其卒，故怖其始。居五年，紂為肉圃，設炮烙，登糟邱，臨酒池，紂遂以亡。故箕子見象箸以知天下之禍，故曰：「見小曰明。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-12_s-1\",\"han-fei-zi_ch-23_p-12_s-2\",\"han-fei-zi_ch-23_p-12_s-3\",\"han-fei-zi_ch-23_p-12_s-4\",\"han-fei-zi_ch-23_p-12_s-5\",\"han-fei-zi_ch-23_p-12_s-6\",\"han-fei-zi_ch-23_p-12_s-7\",\"han-fei-zi_ch-23_p-12_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"昔的人或事物紂為象箸而且箕子怖。以為象箸必不加於土鉶，必將犀玉的杯。象箸玉杯必不羹菽藿，則必旄象豹胎。旄象豹胎必不衣短褐而且食於茅屋的下，則錦衣九重，廣室高臺。吾畏他的卒，所以怖他的始。居五年，紂為肉圃，設炮烙，登糟邱，臨酒池，紂遂以亡。所以箕子見象箸以知天下的禍，因此韓絕不是子評論說道：見小說道：明。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 12 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「昔者紂為象箸而箕子怖」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「昔者紂為象箸而箕子怖。以為象箸必不加於土鉶，必將犀玉……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-13\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":13,\"canonicalText\":\"句踐入宦於吳，身執干戈為吳王洗馬，故能殺夫差於姑蘇。文王見詈於王門，顏色不變，而武王擒紂於牧野。故曰：「守柔曰強。」越王之霸也不病宦，武王之王也不病詈。故曰：「聖人之不病也，以其不病，是以無病也。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-13_s-1\",\"han-fei-zi_ch-23_p-13_s-2\",\"han-fei-zi_ch-23_p-13_s-3\",\"han-fei-zi_ch-23_p-13_s-4\",\"han-fei-zi_ch-23_p-13_s-5\",\"han-fei-zi_ch-23_p-13_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"句踐入宦於吳，身執干戈為吳王洗馬，所以能殺夫差於姑蘇。文王見詈於王門，顏色不變，而且武王擒紂於牧野。因此韓絕不是子評論說道：守柔說道：強。越王的霸啊不病宦，武王的王啊不病詈。因此韓絕不是子評論說道：聖人的不病啊，以他的不病，是以無病啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 13 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「句踐入宦於吳，身執干戈為吳王洗馬，故能殺夫差於姑蘇」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「句踐入宦於吳，身執干戈為吳王洗馬，故能殺夫差於姑蘇。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-14\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":14,\"canonicalText\":\"宋之鄙人得璞玉而獻之子罕，子罕不受，鄙人曰：「此寶也，宜為君子器，不宜為細人用。」子罕曰：「爾以玉為寶，我以不受子玉為寶。」是鄙人慾玉，而子罕不欲玉。故曰：「欲不欲，而不貴難得之貨。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-14_s-1\",\"han-fei-zi_ch-23_p-14_s-2\",\"han-fei-zi_ch-23_p-14_s-3\",\"han-fei-zi_ch-23_p-14_s-4\",\"han-fei-zi_ch-23_p-14_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"宋的鄙人得璞玉而且獻的子罕，子罕不受，鄙人說道：此寶啊，宜為君主統治者子器，不宜為細人用。子罕說道：爾以玉為寶，我以不受子玉為寶。是鄙人慾玉，而且子罕不欲玉。因此韓絕不是子評論說道：欲不欲，而且不貴難得的貨。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 14 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「宋之鄙人得璞玉而獻之子罕，子罕不受，鄙人曰：「此寶也，宜為君子器，不宜為細人用」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「宋之鄙人得璞玉而獻之子罕，子罕不受，鄙人曰：「此寶也……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-15\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":15,\"canonicalText\":\"王壽負書而行，見徐馮於周塗，馮曰：「事者，為也。為生於時，知者無常事。書者，言也。言生於知，知者不藏書。今子何獨負之而行？」於是王壽因焚其書而舞之。故知者不以言談教，而慧者不以藏書篋。此世之所過也，而王壽復之，是學不學也。故曰：「學不學，復歸眾人之所過也。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-15_s-1\",\"han-fei-zi_ch-23_p-15_s-2\",\"han-fei-zi_ch-23_p-15_s-3\",\"han-fei-zi_ch-23_p-15_s-4\",\"han-fei-zi_ch-23_p-15_s-5\",\"han-fei-zi_ch-23_p-15_s-6\",\"han-fei-zi_ch-23_p-15_s-7\",\"han-fei-zi_ch-23_p-15_s-8\",\"han-fei-zi_ch-23_p-15_s-9\",\"han-fei-zi_ch-23_p-15_s-10\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"王壽負書而且行，見徐馮於周塗，馮說道：事的人或事物，為啊。為生於時，知的人或事物無常事。書的人或事物，言啊。言生於知，知的人或事物不藏書。今子何獨負的而且行？於是王壽因焚他的書而且舞的。所以知的人或事物不以言談教，而且慧的人或事物不以藏書篋。此世的所過啊，而且王壽復的，是學不學啊。因此韓絕不是子評論說道：學不學，復歸眾人的所過啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 15 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「王壽負書而行，見徐馮於周塗，馮曰：「事者，為也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「王壽負書而行，見徐馮於周塗，馮曰：「事者，為也。為生……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-16\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":16,\"canonicalText\":\"夫物有常容，因乘以導之，因隨物之容。故靜則建乎德，動則順乎道。宋人有為其君以象為楮葉者，三年而成。豐殺莖柯，毫芒繁澤，亂之楮葉之中而不可別也。此人遂以功食祿於宋邦。列子聞之曰：「使天地三年而成一葉，則物之有葉者寡矣。」故不乘天地之資，而載一人之身；不隨道理之數，而學一人之智；此皆一葉之行也。故冬耕之稼，后稷不能羨也；豐年大禾，臧獲不能惡也。以一人力，則后稷不足；隨自然，則臧獲有餘。故曰：「恃萬物之自然而不敢為也。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-16_s-1\",\"han-fei-zi_ch-23_p-16_s-2\",\"han-fei-zi_ch-23_p-16_s-3\",\"han-fei-zi_ch-23_p-16_s-4\",\"han-fei-zi_ch-23_p-16_s-5\",\"han-fei-zi_ch-23_p-16_s-6\",\"han-fei-zi_ch-23_p-16_s-7\",\"han-fei-zi_ch-23_p-16_s-8\",\"han-fei-zi_ch-23_p-16_s-9\",\"han-fei-zi_ch-23_p-16_s-10\",\"han-fei-zi_ch-23_p-16_s-11\",\"han-fei-zi_ch-23_p-16_s-12\",\"han-fei-zi_ch-23_p-16_s-13\",\"han-fei-zi_ch-23_p-16_s-14\",\"han-fei-zi_ch-23_p-16_s-15\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"夫物有常容，因乘以導的，因隨物的容。所以靜則建乎德，動則順乎道。宋人有為他的君主統治者以象為楮葉的人或事物，三年而且成。豐殺莖柯，毫芒繁澤，亂的楮葉的中而且不可別啊。此人遂以功食祿於宋邦。列子聞的說道：使天地三年而且成一葉，則物的有葉的人或事物寡矣。所以不乘天地的資，而且載一人的身；不隨道理的數，而且學一人的智；此皆一葉的行啊。所以冬耕的稼，后稷不能羨啊；豐年大禾，臧獲不能惡啊。以一人力，則后稷不足；隨自然，則臧獲有餘。因此韓絕不是子評論說道：恃萬物的自然而且不敢為啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 16 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「夫物有常容，因乘以導之，因隨物之容」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「夫物有常容，因乘以導之，因隨物之容。故靜則建乎德，動……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-17\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":17,\"canonicalText\":\"空竅者，神明之戶牖也。耳目竭於聲色，精神竭於外貌，故中無主。中無主則禍福雖如丘山無從識之，故曰：「不出於戶，可以知天下；不闚於牖，可以知天道。」此言神明之不離其實也。\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-17_s-1\",\"han-fei-zi_ch-23_p-17_s-2\",\"han-fei-zi_ch-23_p-17_s-3\",\"han-fei-zi_ch-23_p-17_s-4\",\"han-fei-zi_ch-23_p-17_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"空竅的人或事物，神明的戶牖啊。耳目竭於聲色，精神竭於外貌，所以中無主。中無主則禍福雖如丘山無從識的，因此韓絕不是子評論說道：不出於戶，可以知天下；不闚於牖，可以知天道。此言神明的不離他的實啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 17 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「空竅者，神明之戶牖也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「空竅者，神明之戶牖也。耳目竭於聲色，精神竭於外貌，故……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-18\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":18,\"canonicalText\":\"趙襄主學御於王子期，俄而與於期逐，三易馬而三後。襄主曰：「子之教我御術未盡也。」對曰：「術已盡，用之則過也。凡御之所貴，馬體安於車，人心調於馬，而後可以進速致遠。今君後則欲逮臣，先則恐逮於臣。夫誘道爭遠，非先則後也。而先後心皆在於臣，上何以調於馬，此君之所以後也。」白公勝慮亂，罷朝，倒杖而策銳貫顊，血流至於地而不知。鄭人聞之曰：「顊之忘，將何為忘哉！」故曰：「其出彌遠者，其智彌少。」此言智周乎遠，則所遺在近也，是以聖人無常行也。能並智，故曰：「不行而知。」能並視，故曰：「不見而明。」隨時以舉事，因資而立功，用萬物之能而獲利其上，故曰：「不為而成。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-18_s-1\",\"han-fei-zi_ch-23_p-18_s-2\",\"han-fei-zi_ch-23_p-18_s-3\",\"han-fei-zi_ch-23_p-18_s-4\",\"han-fei-zi_ch-23_p-18_s-5\",\"han-fei-zi_ch-23_p-18_s-6\",\"han-fei-zi_ch-23_p-18_s-7\",\"han-fei-zi_ch-23_p-18_s-8\",\"han-fei-zi_ch-23_p-18_s-9\",\"han-fei-zi_ch-23_p-18_s-10\",\"han-fei-zi_ch-23_p-18_s-11\",\"han-fei-zi_ch-23_p-18_s-12\",\"han-fei-zi_ch-23_p-18_s-13\",\"han-fei-zi_ch-23_p-18_s-14\",\"han-fei-zi_ch-23_p-18_s-15\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"趙襄主學御於王子期，俄而且與於期逐，三易馬而且三後。襄主說道：子的教我御御臣心術權謀未盡啊。對說道：御臣心術權謀已盡，用的則過啊。凡御的所貴，馬體安於車，人心調於馬，而且後可以進速致遠。今君主統治者後則欲逮臣下僚屬，先則恐逮於臣下僚屬。夫誘道爭遠，絕不是先則後啊。而且先後心皆在於臣下僚屬，上何以調於馬，此君主統治者的所以後啊。白公勝慮亂，罷朝，倒杖而且策銳貫顊，血流至於地而且不知。鄭人聞的說道：顊的忘，將何為忘哉！因此韓絕不是子評論說道：他的出彌遠的人或事物，他的智彌少。此言智周乎遠，則所遺在近啊，是以聖人無常行啊。能並智，因此韓絕不是子評論說道：不行而且知。能並視，因此韓絕不是子評論說道：不見而且明。隨時以舉事，因資而且立功，用萬物的能而且獲利他的上，因此韓絕不是子評論說道：不為而且成。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 18 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「趙襄主學御於王子期，俄而與於期逐，三易馬而三後」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「趙襄主學御於王子期，俄而與於期逐，三易馬而三後。襄主……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-19\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":19,\"canonicalText\":\"楚莊王蒞政三年，無令發，無政為也。右司馬御座而與王隱曰：「有鳥止南方之阜，三年不翅不飛不鳴，嘿然無聲，此為何名？」王曰：「三年不翅，將以長羽翼。不飛不鳴，將以觀民則。雖無飛，飛必沖天；雖無鳴，鳴必驚人。子釋之，不穀知之矣。」處半年，乃自聽政，所廢者十，所起者九，誅大臣五，舉處士六，而邦大治。舉兵誅齊，敗之徐州，勝晉於河雍，合諸侯於宋，遂霸天下。莊王不為小害善，故有大名；不蚤見示，故有大功。故曰：「大器晚成，大音希聲。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-19_s-1\",\"han-fei-zi_ch-23_p-19_s-2\",\"han-fei-zi_ch-23_p-19_s-3\",\"han-fei-zi_ch-23_p-19_s-4\",\"han-fei-zi_ch-23_p-19_s-5\",\"han-fei-zi_ch-23_p-19_s-6\",\"han-fei-zi_ch-23_p-19_s-7\",\"han-fei-zi_ch-23_p-19_s-8\",\"han-fei-zi_ch-23_p-19_s-9\",\"han-fei-zi_ch-23_p-19_s-10\",\"han-fei-zi_ch-23_p-19_s-11\",\"han-fei-zi_ch-23_p-19_s-12\",\"han-fei-zi_ch-23_p-19_s-13\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楚莊王蒞政三年，無令發，無政為啊。右司馬御座而且與王隱說道：有鳥止南方的阜，三年不翅不飛不鳴，嘿然無聲，此為何名？王說道：三年不翅，將以長羽翼。不飛不鳴，將以觀民則。雖無飛，飛必沖天；雖無鳴，鳴必驚人。子釋的，不穀知的矣。處半年，乃自聽政，所廢的人或事物十，所起的人或事物九，誅大臣下僚屬五，舉處士六，而且邦大治。舉兵誅齊，敗的徐州，勝晉於河雍，合諸侯於宋，遂霸天下。莊王不為小害善，所以有大名；不蚤見示，所以有大功。因此韓絕不是子評論說道：大器晚成，大音希聲。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 19 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「楚莊王蒞政三年，無令發，無政為也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「楚莊王蒞政三年，無令發，無政為也。右司馬御座而與王隱……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-20\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":20,\"canonicalText\":\"楚莊王欲伐越，杜子諫曰：「王之伐越何也？」曰：「政亂兵弱。」杜子曰：「臣愚患之。智如目也，能見百步之外而不能自見其睫。王之兵自敗於秦、晉，喪地數百里，此兵之弱也。莊蹻為盜於境內而吏不能禁，此政之亂也。王之弱亂非越之下也，而欲伐越，此智之如目也。」王乃止。故知之難，不在見人，在自見。故曰：「自見之謂明。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-20_s-1\",\"han-fei-zi_ch-23_p-20_s-2\",\"han-fei-zi_ch-23_p-20_s-3\",\"han-fei-zi_ch-23_p-20_s-4\",\"han-fei-zi_ch-23_p-20_s-5\",\"han-fei-zi_ch-23_p-20_s-6\",\"han-fei-zi_ch-23_p-20_s-7\",\"han-fei-zi_ch-23_p-20_s-8\",\"han-fei-zi_ch-23_p-20_s-9\",\"han-fei-zi_ch-23_p-20_s-10\",\"han-fei-zi_ch-23_p-20_s-11\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楚莊王欲伐越，杜子諫說道：王的伐越何啊？說道：政亂兵弱。杜子說道：臣下僚屬愚患的。智如目啊，能見百步的外而且不能自見他的睫。王的兵自敗於秦、晉，喪地數百里，此兵的弱啊。莊蹻為盜於境內而且吏不能禁，此政的亂啊。王的弱亂絕不是越的下啊，而且欲伐越，此智的如目啊。王乃止。所以知的難，不在見人，在自見。因此韓絕不是子評論說道：自見的謂明。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 20 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「楚莊王欲伐越，杜子諫曰：「王之伐越何也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「楚莊王欲伐越，杜子諫曰：「王之伐越何也？」曰：「政亂……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-21\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":21,\"canonicalText\":\"子夏見曾子，曾子曰：「何肥也？」對曰：「戰勝故肥也。」曾子曰：「何謂也？」子夏曰：「吾入見先王之義則榮之，出見富貴之樂又榮之，兩者戰於胸中，未知勝負，故臞。今先王之義勝，故肥。」是以志之難也，不在勝人，在自勝也。故曰：「自勝之謂強。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-21_s-1\",\"han-fei-zi_ch-23_p-21_s-2\",\"han-fei-zi_ch-23_p-21_s-3\",\"han-fei-zi_ch-23_p-21_s-4\",\"han-fei-zi_ch-23_p-21_s-5\",\"han-fei-zi_ch-23_p-21_s-6\",\"han-fei-zi_ch-23_p-21_s-7\",\"han-fei-zi_ch-23_p-21_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子夏見曾子，曾子說道：何肥啊？對說道：戰勝所以肥啊。曾子說道：何謂啊？子夏說道：吾入見先王的義則榮的，出見富貴的樂又榮的，兩的人或事物戰於胸中，未知勝負，所以臞。今先王的義勝，所以肥。是以志的難啊，不在勝人，在自勝啊。因此韓絕不是子評論說道：自勝的謂強。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 21 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「子夏見曾子，曾子曰：「何肥也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「子夏見曾子，曾子曰：「何肥也？」對曰：「戰勝故肥也。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-23_p-22\",\"chapterId\":\"han-fei-zi_ch-23\",\"order\":22,\"canonicalText\":\"周有玉版，紂令膠鬲索之，文王不予，費仲來求，因予之。是膠鬲賢而費仲無道也。周惡賢者之得志也，故予費仲。文王舉太公於渭濱者，貴之也；而資費仲玉版者，是愛之也。故曰：「不貴其師，不愛其資，雖知大迷，是謂要妙。」\",\"sentenceIds\":[\"han-fei-zi_ch-23_p-22_s-1\",\"han-fei-zi_ch-23_p-22_s-2\",\"han-fei-zi_ch-23_p-22_s-3\",\"han-fei-zi_ch-23_p-22_s-4\",\"han-fei-zi_ch-23_p-22_s-5\",\"han-fei-zi_ch-23_p-22_s-6\",\"han-fei-zi_ch-23_p-22_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"周有玉版，紂令膠鬲索的，文王不予，費仲來求，因予的。是膠鬲賢而且費仲無道啊。周惡賢的人或事物的得志啊，所以予費仲。文王舉太公於渭濱的人或事物，貴的啊；而且資費仲玉版的人或事物，是愛的啊。因此韓絕不是子評論說道：不貴他的師，不愛他的資，雖知大迷，是謂要妙。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈喻老〉（第 22 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「周有玉版，紂令膠鬲索之，文王不予，費仲來求，因予之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「周有玉版，紂令膠鬲索之，文王不予，費仲來求，因予之。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"han-fei-zi_ch-23_p-1_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-1\",\"order\":1,\"canonicalText\":\"天下有道無急患則曰靜，遽傳不用，故曰：「卻走馬以糞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-1_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-1\",\"order\":2,\"canonicalText\":\"」天下無道，攻擊不休，相守數年不已，甲冑生蟣蝨，鷰雀處帷幄，而兵不歸，故曰：「戎馬生於郊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-1_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-1\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-2_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-2\",\"order\":1,\"canonicalText\":\"翟人有獻豐狐、玄豹之皮於晉文公，文公受客皮而歎曰：「此以皮之美自為罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-2_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-2\",\"order\":2,\"canonicalText\":\"」夫治國者以名號為罪，徐偃王是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-2_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-2\",\"order\":3,\"canonicalText\":\"以城與地為罪，虞、虢是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-2_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-2\",\"order\":4,\"canonicalText\":\"故曰：「罪莫大於可欲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-2_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-2\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-3_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-3\",\"order\":1,\"canonicalText\":\"智伯兼範、中行而攻趙不已，韓、魏反之，軍敗晉陽，身死高梁之東，遂卒被分，漆其首以為溲器，故曰：「禍莫大於不知足。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-3_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-3\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-4_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-4\",\"order\":1,\"canonicalText\":\"虞君欲屈產之乘，與垂棘之璧，不聽宮之奇，故邦亡身死，故曰：「咎莫憯於欲得。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-4_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-4\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-5_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-5\",\"order\":1,\"canonicalText\":\"邦以存為常，霸王其可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-5_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-5\",\"order\":2,\"canonicalText\":\"身以生為常，富貴其可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-5_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-5\",\"order\":3,\"canonicalText\":\"不欲自害則邦不亡身不死，故曰：「知足之為足矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-5_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-5\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-6_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-6\",\"order\":1,\"canonicalText\":\"楚莊王既勝狩於河雍，歸而賞孫叔敖，孫叔敖請漢間之地，沙石之處。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-6_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-6\",\"order\":2,\"canonicalText\":\"楚邦之法，祿臣再世而收地，唯孫叔敖獨在。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-6_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-6\",\"order\":3,\"canonicalText\":\"此不以其邦為收者，瘠也，故九世而祀不絕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-6_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-6\",\"order\":4,\"canonicalText\":\"故曰：「善建不拔，善抱不脫，子孫以其祭祀世世不輟」，孫叔敖之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":1,\"canonicalText\":\"制在己曰重，不離位曰靜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":2,\"canonicalText\":\"重則能使輕，靜則能使躁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":3,\"canonicalText\":\"故曰：「重為輕根，靜為躁君。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":4,\"canonicalText\":\"故曰君子終日行不離輜重也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":5,\"canonicalText\":\"」邦者，人君之輜重也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":6,\"canonicalText\":\"主父生傳其邦，此離其輜重者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":7,\"canonicalText\":\"故雖有代、雲中之樂，超然已無趙矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":8,\"canonicalText\":\"主父，萬乘之主，而以身輕於天下，無勢之謂輕，離位之謂躁，是以生幽而死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-7_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-7\",\"order\":9,\"canonicalText\":\"故曰：「輕則失臣，躁則失君」，主父之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":1,\"canonicalText\":\"勢重者，人君之淵也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":2,\"canonicalText\":\"君人者勢重於人臣之閒，失則不可復得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":3,\"canonicalText\":\"簡公失之於田成，晉公失之於六卿，而邦亡身死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":4,\"canonicalText\":\"故曰：「魚不可脫於深淵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":5,\"canonicalText\":\"」賞罰者，邦之利器也，在君則制臣，在臣則勝君。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":6,\"canonicalText\":\"君見賞，臣則損之以為德；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":7,\"canonicalText\":\"君見罰，臣則益之以為威。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":8,\"canonicalText\":\"人君見賞而人臣用其勢，人君見罰而人臣乘其威。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":9,\"canonicalText\":\"故曰：「邦之利器不可以示人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-8_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-8\",\"order\":10,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":1,\"canonicalText\":\"越王入宦於吳，而觀之伐齊以弊吳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":2,\"canonicalText\":\"吳兵既勝齊人於艾陵，張之於江、濟，強之於黃池，故可制於五湖。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":3,\"canonicalText\":\"故曰：「將欲翕之，必固張之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":4,\"canonicalText\":\"將欲弱之，必固強之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":5,\"canonicalText\":\"」晉獻公將欲襲虞，遺之以璧馬；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":6,\"canonicalText\":\"知伯將襲仇由，遺之以廣車。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":7,\"canonicalText\":\"故曰：「將欲取之，必固與之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":8,\"canonicalText\":\"」起事於無形，而要大功於天下，是謂微明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-9_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-9\",\"order\":9,\"canonicalText\":\"處小弱而重自卑謂損弱勝強也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":1,\"canonicalText\":\"有形之類，大必起於小；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":2,\"canonicalText\":\"行久之物，族必起於少。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":3,\"canonicalText\":\"故曰：「天下之難事必作於易，天下之大事必作於細。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":4,\"canonicalText\":\"」是以欲制物者於其細也，故曰：「圖難於其易也，為大於其細也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":5,\"canonicalText\":\"」千丈之隄以螻蟻之穴潰，百尺之室以突隙之煙焚。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":6,\"canonicalText\":\"故曰：白圭之行隄也塞其穴，丈人之慎火也塗其隙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":7,\"canonicalText\":\"是以白圭無水難，丈人無火患。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":8,\"canonicalText\":\"此皆慎易以避難，敬細以遠大者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":9,\"canonicalText\":\"扁鵲見蔡桓公，立有間，扁鵲曰：「君有疾在腠理，不治將恐深。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":10,\"canonicalText\":\"」桓侯曰：「寡人無。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":11,\"canonicalText\":\"」扁鵲出，桓侯曰：「醫之好治不病以為功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":12,\"canonicalText\":\"」居十日，扁鵲復見曰：「君之病在肌膚，不治將益深。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":13,\"canonicalText\":\"」桓侯不應。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":14,\"canonicalText\":\"扁鵲出，桓侯又不悅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":15,\"canonicalText\":\"居十日，扁鵲復見曰：「君之病在腸胃，不治將益深。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":16,\"canonicalText\":\"」桓侯又不應。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":17,\"canonicalText\":\"扁鵲出，桓侯又不悅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":18,\"canonicalText\":\"居十日，扁鵲望桓侯而還走。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":19,\"canonicalText\":\"桓侯故使人問之，扁鵲曰：「疾在腠理，湯熨之所及也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":20,\"canonicalText\":\"在肌膚，鍼石之所及也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":21,\"canonicalText\":\"在腸胃，火齊之所及也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-22\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":22,\"canonicalText\":\"在骨髓，司命之所屬，無奈何也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-23\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":23,\"canonicalText\":\"今在骨髓，臣是以無請也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-24\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":24,\"canonicalText\":\"」居五日，桓公體痛，使人索扁鵲，已逃秦矣，桓侯遂死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-25\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":25,\"canonicalText\":\"故良醫之治病也，攻之於腠理，此皆爭之於小者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-10_s-26\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-10\",\"order\":26,\"canonicalText\":\"夫事之禍福亦有腠理之地，故曰：聖人蚤從事焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":1,\"canonicalText\":\"昔晉公子重耳出亡過鄭，鄭君不禮，叔瞻諫曰：「此賢公子也，君厚待之，可以積德。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":2,\"canonicalText\":\"」鄭君不聽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":3,\"canonicalText\":\"叔瞻又諫曰：「不厚待之，不若殺之，無令有後患。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":4,\"canonicalText\":\"」鄭君又不聽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":5,\"canonicalText\":\"及公子返晉邦，舉兵伐鄭，大破之，取八城焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":6,\"canonicalText\":\"晉獻公以垂棘之璧假道於虞而伐虢，大夫宮之奇諫曰：「不可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":7,\"canonicalText\":\"脣亡而齒寒，虞、虢相救，非相德也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":8,\"canonicalText\":\"今日晉滅虢，明日虞必隨之亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":9,\"canonicalText\":\"」虞君不聽，受其璧而假之道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":10,\"canonicalText\":\"晉已取虢，還，反滅虞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":11,\"canonicalText\":\"此二臣者皆爭於腠理者也，而二君不用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":12,\"canonicalText\":\"然則叔瞻、宮之奇亦虞、鄭之扁鵲也，而二君不聽，故鄭以破，虞以亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":13,\"canonicalText\":\"故曰：「其安易持也，其未兆易謀也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-11_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-11\",\"order\":14,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-12_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-12\",\"order\":1,\"canonicalText\":\"昔者紂為象箸而箕子怖。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-12_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-12\",\"order\":2,\"canonicalText\":\"以為象箸必不加於土鉶，必將犀玉之杯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-12_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-12\",\"order\":3,\"canonicalText\":\"象箸玉杯必不羹菽藿，則必旄象豹胎。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-12_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-12\",\"order\":4,\"canonicalText\":\"旄象豹胎必不衣短褐而食於茅屋之下，則錦衣九重，廣室高臺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-12_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-12\",\"order\":5,\"canonicalText\":\"吾畏其卒，故怖其始。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-12_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-12\",\"order\":6,\"canonicalText\":\"居五年，紂為肉圃，設炮烙，登糟邱，臨酒池，紂遂以亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-12_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-12\",\"order\":7,\"canonicalText\":\"故箕子見象箸以知天下之禍，故曰：「見小曰明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-12_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-12\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-13_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-13\",\"order\":1,\"canonicalText\":\"句踐入宦於吳，身執干戈為吳王洗馬，故能殺夫差於姑蘇。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-13_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-13\",\"order\":2,\"canonicalText\":\"文王見詈於王門，顏色不變，而武王擒紂於牧野。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-13_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-13\",\"order\":3,\"canonicalText\":\"故曰：「守柔曰強。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-13_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-13\",\"order\":4,\"canonicalText\":\"」越王之霸也不病宦，武王之王也不病詈。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-13_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-13\",\"order\":5,\"canonicalText\":\"故曰：「聖人之不病也，以其不病，是以無病也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-13_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-13\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-14_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-14\",\"order\":1,\"canonicalText\":\"宋之鄙人得璞玉而獻之子罕，子罕不受，鄙人曰：「此寶也，宜為君子器，不宜為細人用。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-14_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-14\",\"order\":2,\"canonicalText\":\"」子罕曰：「爾以玉為寶，我以不受子玉為寶。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-14_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-14\",\"order\":3,\"canonicalText\":\"」是鄙人慾玉，而子罕不欲玉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-14_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-14\",\"order\":4,\"canonicalText\":\"故曰：「欲不欲，而不貴難得之貨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-14_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-14\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":1,\"canonicalText\":\"王壽負書而行，見徐馮於周塗，馮曰：「事者，為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":2,\"canonicalText\":\"為生於時，知者無常事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":3,\"canonicalText\":\"書者，言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":4,\"canonicalText\":\"言生於知，知者不藏書。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":5,\"canonicalText\":\"今子何獨負之而行？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":6,\"canonicalText\":\"」於是王壽因焚其書而舞之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":7,\"canonicalText\":\"故知者不以言談教，而慧者不以藏書篋。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":8,\"canonicalText\":\"此世之所過也，而王壽復之，是學不學也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":9,\"canonicalText\":\"故曰：「學不學，復歸眾人之所過也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-15_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-15\",\"order\":10,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":1,\"canonicalText\":\"夫物有常容，因乘以導之，因隨物之容。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":2,\"canonicalText\":\"故靜則建乎德，動則順乎道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":3,\"canonicalText\":\"宋人有為其君以象為楮葉者，三年而成。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":4,\"canonicalText\":\"豐殺莖柯，毫芒繁澤，亂之楮葉之中而不可別也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":5,\"canonicalText\":\"此人遂以功食祿於宋邦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":6,\"canonicalText\":\"列子聞之曰：「使天地三年而成一葉，則物之有葉者寡矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":7,\"canonicalText\":\"」故不乘天地之資，而載一人之身；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":8,\"canonicalText\":\"不隨道理之數，而學一人之智；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":9,\"canonicalText\":\"此皆一葉之行也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":10,\"canonicalText\":\"故冬耕之稼，后稷不能羨也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":11,\"canonicalText\":\"豐年大禾，臧獲不能惡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":12,\"canonicalText\":\"以一人力，則后稷不足；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":13,\"canonicalText\":\"隨自然，則臧獲有餘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":14,\"canonicalText\":\"故曰：「恃萬物之自然而不敢為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-16_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-16\",\"order\":15,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-17_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-17\",\"order\":1,\"canonicalText\":\"空竅者，神明之戶牖也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-17_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-17\",\"order\":2,\"canonicalText\":\"耳目竭於聲色，精神竭於外貌，故中無主。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-17_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-17\",\"order\":3,\"canonicalText\":\"中無主則禍福雖如丘山無從識之，故曰：「不出於戶，可以知天下；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-17_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-17\",\"order\":4,\"canonicalText\":\"不闚於牖，可以知天道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-17_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-17\",\"order\":5,\"canonicalText\":\"」此言神明之不離其實也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":1,\"canonicalText\":\"趙襄主學御於王子期，俄而與於期逐，三易馬而三後。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":2,\"canonicalText\":\"襄主曰：「子之教我御術未盡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":3,\"canonicalText\":\"」對曰：「術已盡，用之則過也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":4,\"canonicalText\":\"凡御之所貴，馬體安於車，人心調於馬，而後可以進速致遠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":5,\"canonicalText\":\"今君後則欲逮臣，先則恐逮於臣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":6,\"canonicalText\":\"夫誘道爭遠，非先則後也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":7,\"canonicalText\":\"而先後心皆在於臣，上何以調於馬，此君之所以後也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":8,\"canonicalText\":\"」白公勝慮亂，罷朝，倒杖而策銳貫顊，血流至於地而不知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":9,\"canonicalText\":\"鄭人聞之曰：「顊之忘，將何為忘哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":10,\"canonicalText\":\"」故曰：「其出彌遠者，其智彌少。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":11,\"canonicalText\":\"」此言智周乎遠，則所遺在近也，是以聖人無常行也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":12,\"canonicalText\":\"能並智，故曰：「不行而知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":13,\"canonicalText\":\"」能並視，故曰：「不見而明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":14,\"canonicalText\":\"」隨時以舉事，因資而立功，用萬物之能而獲利其上，故曰：「不為而成。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-18_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-18\",\"order\":15,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":1,\"canonicalText\":\"楚莊王蒞政三年，無令發，無政為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":2,\"canonicalText\":\"右司馬御座而與王隱曰：「有鳥止南方之阜，三年不翅不飛不鳴，嘿然無聲，此為何名？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":3,\"canonicalText\":\"」王曰：「三年不翅，將以長羽翼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":4,\"canonicalText\":\"不飛不鳴，將以觀民則。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":5,\"canonicalText\":\"雖無飛，飛必沖天；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":6,\"canonicalText\":\"雖無鳴，鳴必驚人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":7,\"canonicalText\":\"子釋之，不穀知之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":8,\"canonicalText\":\"」處半年，乃自聽政，所廢者十，所起者九，誅大臣五，舉處士六，而邦大治。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":9,\"canonicalText\":\"舉兵誅齊，敗之徐州，勝晉於河雍，合諸侯於宋，遂霸天下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":10,\"canonicalText\":\"莊王不為小害善，故有大名；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":11,\"canonicalText\":\"不蚤見示，故有大功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":12,\"canonicalText\":\"故曰：「大器晚成，大音希聲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-19_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-19\",\"order\":13,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":1,\"canonicalText\":\"楚莊王欲伐越，杜子諫曰：「王之伐越何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":2,\"canonicalText\":\"」曰：「政亂兵弱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":3,\"canonicalText\":\"」杜子曰：「臣愚患之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":4,\"canonicalText\":\"智如目也，能見百步之外而不能自見其睫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":5,\"canonicalText\":\"王之兵自敗於秦、晉，喪地數百里，此兵之弱也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":6,\"canonicalText\":\"莊蹻為盜於境內而吏不能禁，此政之亂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":7,\"canonicalText\":\"王之弱亂非越之下也，而欲伐越，此智之如目也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":8,\"canonicalText\":\"」王乃止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":9,\"canonicalText\":\"故知之難，不在見人，在自見。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":10,\"canonicalText\":\"故曰：「自見之謂明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-20_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-20\",\"order\":11,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-21_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-21\",\"order\":1,\"canonicalText\":\"子夏見曾子，曾子曰：「何肥也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-21_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-21\",\"order\":2,\"canonicalText\":\"」對曰：「戰勝故肥也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-21_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-21\",\"order\":3,\"canonicalText\":\"」曾子曰：「何謂也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-21_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-21\",\"order\":4,\"canonicalText\":\"」子夏曰：「吾入見先王之義則榮之，出見富貴之樂又榮之，兩者戰於胸中，未知勝負，故臞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-21_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-21\",\"order\":5,\"canonicalText\":\"今先王之義勝，故肥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-21_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-21\",\"order\":6,\"canonicalText\":\"」是以志之難也，不在勝人，在自勝也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-21_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-21\",\"order\":7,\"canonicalText\":\"故曰：「自勝之謂強。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-21_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-21\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-22_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-22\",\"order\":1,\"canonicalText\":\"周有玉版，紂令膠鬲索之，文王不予，費仲來求，因予之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-22_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-22\",\"order\":2,\"canonicalText\":\"是膠鬲賢而費仲無道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-22_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-22\",\"order\":3,\"canonicalText\":\"周惡賢者之得志也，故予費仲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-22_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-22\",\"order\":4,\"canonicalText\":\"文王舉太公於渭濱者，貴之也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-22_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-22\",\"order\":5,\"canonicalText\":\"而資費仲玉版者，是愛之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-22_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-22\",\"order\":6,\"canonicalText\":\"故曰：「不貴其師，不愛其資，雖知大迷，是謂要妙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-23_p-22_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-23\",\"passageId\":\"han-fei-zi_ch-23_p-22\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
